// Konfigurasi competitor domains
const competitors = [
  { domain: 'competitor1.com', name: 'Competitor A' },
  { domain: 'competitor2.com', name: 'Competitor B' },
  { domain: 'competitor3.com', name: 'Competitor C' }
];

const ourDomain = $env.COMPANY_DOMAIN || 'ourdomain.com';

return competitors.map(c => ({
  json: {
    competitor_domain: c.domain,
    competitor_name: c.name,
    our_domain: ourDomain
  }
}));

const response = $input.first().json;
const competitorData = $node['Define Competitors'].json;
const keywords = response.keywords || response.organic_keywords || [];
const results = [];

for (const kw of keywords) {
  results.push({
    json: {
      competitor_domain: competitorData.competitor_domain,
      competitor_name: competitorData.competitor_name,
      our_domain: competitorData.our_domain,
      keyword: kw.keyword || kw.term,
      competitor_position: kw.position || kw.rank,
      search_volume: kw.volume || kw.search_volume,
      traffic: kw.traffic || 0,
      keyword_difficulty: kw.difficulty || kw.kd || 0
    }
  });
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const prevNode = $node['Parse Competitor Data'].json;
  const ourPosition = data.position || null;
  const competitorPosition = prevNode.competitor_position;

  const gap = ourPosition && competitorPosition 
    ? ourPosition - competitorPosition 
    : null;

  results.push({
    json: {
      ...prevNode,
      our_position: ourPosition,
      gap: gap,
      opportunity: !ourPosition || ourPosition > 10 ? 'high' : 
                   ourPosition > competitorPosition ? 'medium' : 'low'
    }
  });
}

return results;

const allData = $input.all().map(i => i.json);

// Summarize opportunities
const highOpportunities = allData.filter(d => d.opportunity === 'high');
const totalKeywords = allData.length;
const avgGap = allData.filter(d => d.gap).reduce((sum, d) => sum + Math.abs(d.gap), 0) / (allData.filter(d => d.gap).length || 1);

// Top opportunities by volume
const topOpportunities = highOpportunities
  .sort((a, b) => (b.search_volume || 0) - (a.search_volume || 0))
  .slice(0, 10);

return [{
  json: {
    summary: {
      total_keywords_analyzed: totalKeywords,
      high_opportunities: highOpportunities.length,
      average_position_gap: Math.round(avgGap),
      top_opportunities: topOpportunities.map(o => ({
        keyword: o.keyword,
        competitor: o.competitor_name,
        their_position: o.competitor_position,
        our_position: o.our_position || 'Not ranking',
        volume: o.search_volume
      }))
    }
  }
}];

